import type { ChartDataset, ChartOptions } from 'chart.js';

import type { SustainableGrowthOverviewData } from './types';

type BarChartData = SustainableGrowthOverviewData['barChart'];

export const DEFAULT_CHART_COLORS = {
  striped: '#e9c528',
  current: '#d1a33c',
  default: '#eddab1',
} as const;

export function getBarChartDatasetsWithColors(
  barChart: BarChartData,
  chartColors: {
    striped: string;
    current: string;
    default: string;
  },
): ChartDataset<'bar'>[] {
  if (!barChart) return [];
  const labels = barChart.labels ?? [];
  const stripedIndexes = barChart.stripedIndexes ?? [];
  const highlightLabels = barChart.highlightLabels ?? [];
  const firstDataset = barChart.datasets?.[0];

  const backgroundColor = labels.map((label, index) => {
    if (stripedIndexes.includes(index)) return chartColors.striped;
    if (highlightLabels.includes(label)) return chartColors.current;
    return chartColors.default;
  });

  return firstDataset
    ? [{ ...firstDataset, backgroundColor }]
    : (barChart.datasets ?? []);
}

const CHART_AREA_HEIGHT_PX = 190;
const DATALABEL_HEIGHT_PX = 28;
const MAX_BUFFERED_SPACING = 0.15;

export function getNegativeBarChartOptions(
  barChart: BarChartData,
): ChartOptions | undefined {
  if (!barChart?.datasets?.length) return undefined;

  const numericValues = barChart.datasets.flatMap((dataset) =>
    (dataset.data ?? []).filter((v): v is number => typeof v === 'number'),
  );

  const actualMin = Math.min(0, ...numericValues);
  if (actualMin >= 0) return undefined;

  const actualMax = Math.max(0, ...numericValues);
  const maxBuffered = actualMax * (1 + MAX_BUFFERED_SPACING);

  const dynamicMin =
    (CHART_AREA_HEIGHT_PX * actualMin - DATALABEL_HEIGHT_PX * maxBuffered) /
    (CHART_AREA_HEIGHT_PX - DATALABEL_HEIGHT_PX);

  return { scales: { y: { min: dynamicMin } } };
}
